-- ONE-TIME TEST DATA SEED (not a migration).
--
-- Adds clearly-labelled sample data so every admin section has something to show:
--   2 customers ("... (TEST)"), 50 synthetic employees (@example.com),
--   4 surveys (3 published with responses, 1 unpublished draft), invitations and
--   ~100 responses. Everything is fictional and every name says TEST.
--
-- Runs as a temporary team member "seed-bot@example.test" (removed at the end) so
-- the real provisioning function (ensure_survey_response_table) creates the
-- response tables exactly as the app does - the seed exercises that path rather
-- than hand-writing DDL. Audit entries from the run carry that actor.
--
-- Answers are random draws (random(), not seeded), shaped so results look
-- plausible: NPS and satisfaction correlate, retention risk follows eNPS, and
-- customer satisfaction drifts upward over the last 45 days.
--
-- Guarded: refuses to run twice. Undo with ops/remove_test_data.sql.
-- Generated by a script; the survey definitions below are what the builder stores.

begin;

do $guard$
begin
  if exists (select 1 from public.organizations where slug in ('northwind-demo-test', 'globex-demo-test')) then
    raise exception 'Test data is already present. Run ops/remove_test_data.sql first.';
  end if;
  if exists (select 1 from public.survey_members where lower(email) = 'seed-bot@example.test') then
    raise exception 'A leftover seed-bot@example.test member exists; delete it and retry.';
  end if;
end $guard$;

-- Temporary actor, scoped to this transaction.
insert into public.survey_members (email, organization_id, role, is_active, can_view_identity)
values ('seed-bot@example.test', null, 'owner', true, false);
select set_config('request.jwt.claims', '{"email":"seed-bot@example.test","role":"authenticated"}', true);

-- Random-draw helpers (session-local, gone at commit).
create function pg_temp.g(mean float8, sd float8) returns float8 language sql
  as $$ select mean + sd * (random() + random() + random() - 1.5) * 1.6 $$;
create function pg_temp.ci(x float8, lo int, hi int) returns int language sql
  as $$ select greatest(lo, least(hi, round(x)::int)) $$;
create function pg_temp.pick(a text[]) returns text language sql
  as $$ select a[1 + floor(random() * array_length(a, 1))::int] $$;
create function pg_temp.shuf(a text[]) returns text[] language sql
  as $$ select array_agg(x order by random()) from unnest(a) x $$;

insert into public.organizations (name, slug, is_active) values
  ('Northwind Demo Co (TEST)', 'northwind-demo-test', true),
  ('Globex Demo Ltd (TEST)', 'globex-demo-test', true);

-- 50 synthetic employees: 30 Northwind, 20 Globex.
insert into public.employees (organization_id, employee_code, employee_name, email, department, designation, location, is_active)
select o.id,
       c.prefix || '-' || lpad(i::text, 3, '0'),
       n.first_names[1 + (i * 7 + c.shift) % array_length(n.first_names, 1)] || ' ' || n.last_names[1 + (i * 5 + c.shift) % array_length(n.last_names, 1)],
       lower(n.first_names[1 + (i * 7 + c.shift) % array_length(n.first_names, 1)] || '.' || n.last_names[1 + (i * 5 + c.shift) % array_length(n.last_names, 1)] || '.' || c.prefix || i) || '@example.com',
       c.depts[1 + (i - 1) % array_length(c.depts, 1)],
       c.desigs[1 + (i * 3) % array_length(c.desigs, 1)],
       c.locs[1 + (i * 2 - 1) % array_length(c.locs, 1)],
       true
from (values
  ('northwind-demo-test', 'NW', 30, 0,
    array['Engineering','Engineering','Operations','Sales','Engineering','Operations','Finance','People','Sales','Engineering','Operations','Finance'],
    array['Bengaluru','Bengaluru','Chennai','Remote','Chennai'],
    array['Associate','Senior Associate','Lead','Manager']),
  ('globex-demo-test', 'GX', 20, 11,
    array['Customer Success','Sales','Customer Success','Product','Sales'],
    array['Mumbai','Pune','Mumbai'],
    array['Executive','Senior Executive','Manager'])
) as c(org_slug, prefix, cnt, shift, depts, locs, desigs)
join public.organizations o on o.slug = c.org_slug
cross join lateral generate_series(1, c.cnt) i
cross join lateral (select array['Aarav','Diya','Kabir','Meera','Rohan','Ananya','Vikram','Isha','Arjun','Priya','Neel','Sara','Rahul','Tara','Dev','Nisha','Karan','Leela','Sameer','Zoya'] as first_names,
                           array['Sharma','Iyer','Menon','Patel','Reddy','Nair','Singh','Das','Joshi','Rao','Kulkarni','Bose','Khan','Pillai','Gupta'] as last_names) n;

