o":"s5"}],"questions":[{"id":"stay","type":"yesno","label":"Have you thought about leaving in the last three months?","required":true,"yesLabel":"Yes","noLabel":"No"},{"id":"perks","type":"ranking","label":"Rank these perks from most to least valuable.","required":true,"randomize":true,"options":["Flexible hours","Learning budget","Health cover","Performance bonus","Extra leave"]}]},{"id":"s4","title":"Staying with us","randomizeQuestions":false,"questions":[{"id":"leave_reasons","type":"checkbox","label":"What are the main reasons?","required":true,"randomize":true,"maxSelections":3,"options":["Pay","Career growth","My manager","Workload","Culture","Other"],"otherColumn":"leave_reasons_other"},{"id":"retention_offer","type":"radio","label":"What would most help you stay?","required":true,"options":["A pay review","A clearer career path","A change of team","More flexibility","Nothing would change my mind"]}]},{"id":"s5","title":"Final thoughts","questions":[{"id":"comment","type":"textarea","label":"Anything else you would like leadership to hear?","required":false,"maxLength":800}]}]}'::jsonb, 'survey_test_engagement_pulse', true, o.id, 1, 'CONFIDENTIAL'::survey_privacy_mode, 'Engagement', 'Test data: quarterly eNPS and engagement pulse.', 'seed-bot@example.test'
