-- ── Engagement pulse (CONFIDENTIAL): 24 of 30 employees respond ─────────
create temp table _eng_takers on commit drop as
  select e.id, e.department, e.location, e.designation
  from public.employees e join public.organizations o on o.id = e.organization_id
  where o.slug = 'northwind-demo-test' order by random() limit 24;

with mood as (
  select t.*, pg_temp.g(case t.department when 'Operations' then 5.5 when 'Engineering' then 7.2 else 6.8 end, 1.6) as m from _eng_takers t
), b as (
  select mood.*, pg_temp.ci(pg_temp.g(m, 1.4), 0, 10) as enps from mood
), b2 as (
  select b.*, case when random() < (case when enps >= 8 then 0.08 when enps >= 7 then 0.25 else 0.62 end) then 'No' else 'Yes' end as stay from b
), b3 as (
  select b2.*, case when stay = 'No' then (pg_temp.shuf(array['Pay','Career growth','My manager','Workload','Culture','Other']))[1:1 + floor(random() * 3)::int] else '{}'::text[] end as reasons from b2
)
insert into public.survey_test_engagement_pulse
  (submitted_at, definition_version, tenure, workmode, enps, enps_why, manager_support,
   culture_01, culture_02, culture_03, culture_04, culture_05, workload, stay, perks,
   leave_reasons, leave_reasons_other, retention_offer, comment,
   employee_id, resp_department, resp_location, resp_designation)
select now() - random() * interval '21 days', 1,
       floor(random() * 9)::text, pg_temp.pick(array['Office','Hybrid','Hybrid','Hybrid','Remote']),
       enps::text,
       case when enps <= 6 then pg_temp.pick(array['Workload has been heavy for months.','Not much visibility on career growth.','Tools and processes slow us down.','Communication between teams is poor.','Pay does not match the market.']) end,
       pg_temp.ci(pg_temp.g(m / 2 + 0.2, 0.9), 1, 5)::text,
       (array['Strongly disagree','Disagree','Neutral','Agree','Strongly agree'])[1 + pg_temp.ci(pg_temp.g(m / 2 - 0.2, 0.9), 0, 4)], (array['Strongly disagree','Disagree','Neutral','Agree','Strongly agree'])[1 + pg_temp.ci(pg_temp.g(m / 2 - 0.2, 0.9), 0, 4)],
       (array['Strongly disagree','Disagree','Neutral','Agree','Strongly agree'])[1 + pg_temp.ci(pg_temp.g(m / 2 - 0.2, 0.9), 0, 4)], (array['Strongly disagree','Disagree','Neutral','Agree','Strongly agree'])[1 + pg_temp.ci(pg_temp.g(m / 2 - 0.2, 0.9), 0, 4)],
       (array['Strongly disagree','Disagree','Neutral','Agree','Strongly agree'])[1 + pg_temp.ci(pg_temp.g(m / 2 - 0.2, 0.9), 0, 4)],
       (pg_temp.ci(pg_temp.g(case when department = 'Operations' then 80 else 62 end, 14) / 5, 0, 20) * 5)::text,
       stay, pg_temp.shuf(array['Flexible hours','Learning budget','Health cover','Performance bonus','Extra leave']),
       reasons, case when 'Other' = any(reasons) then 'Long commute' end,
       case when stay = 'No' then pg_temp.pick(array['A pay review','A clearer career path','A change of team','More flexibility','Nothing would change my mind']) end,
       case when random() < 0.4 then pg_temp.pick(array['More recognition for the small wins, please.','Quarterly town halls have really helped.','Please keep hybrid working.','Would love a clearer promotion framework.']) end,
       id, department, location, designation
from b3;

insert into public.survey_invitations (survey_id, survey_version, employee_id, token_hash, status, sent_at, opened_at, started_at, completed_at, expires_at)
select s.id, 1, e.id, encode(extensions.digest(gen_random_uuid()::text, 'sha256'), 'hex'), x.status::invitation_status,
       now() - interval '20 days',
       case when x.status in ('OPENED','STARTED','COMPLETED') then now() - interval '19 days' end,
       case when x.status in ('STARTED','COMPLETED') then date_trunc('hour', now() - interval '18 days') end,
       case when x.status = 'COMPLETED' then date_trunc('hour', now() - interval '10 days') end,
       now() + interval '30 days'
from public.surveys s
join public.organizations o on o.id = s.organization_id
join public.employees e on e.organization_id = o.id
cross join lateral (select case when e.id in (select id from _eng_takers) then 'COMPLETED' else pg_temp.pick(array['SENT','SENT','OPENED','STARTED']) end as status) x
where s.slug = 'test-engagement-pulse';

-- ── Customer satisfaction (ANONYMOUS, open link): 64 responses over 45 days ──
with a as (
  select i, floor(random() * 45)::int as age,
         pg_temp.pick(array['Starter','Starter','Starter','Starter','Pro','Pro','Pro','Pro','Pro','Enterprise','Enterprise','Enterprise']) as plan
  from generate_series(1, 64) i
), b as (
  select a.*, pg_temp.g(6.6 + (45 - age) / 45.0 * 0.9 + case plan when 'Enterprise' then 0.8 when 'Starter' then -0.6 else 0 end, 1.8) as sat,
         random() < 0.42 as support from a
)
insert into public.survey_test_customer_satisfaction
  (submitted_at, definition_version, plan, customer_nps, csat, effort, used_support, support_rating,
   priorities, channels, monthly_spend, renew, anything_else)
select now() - age * interval '1 day' - random() * interval '20 hours', 1,
       plan, pg_temp.ci(sat, 0, 10)::text, pg_temp.ci(sat / 2 + pg_temp.g(0, 0.5), 1, 5)::text, pg_temp.ci(sat * 0.7 + pg_temp.g(0, 0.9), 1, 7)::text,
       case when support then 'Yes' else 'No' end, case when support then pg_temp.ci(pg_temp.g(3.9, 1.0), 1, 5)::text end,
       pg_temp.shuf(array['Speed','Price','Quality','Support','Range']),
       coalesce((pg_temp.shuf(array['Email','Phone','Chat','In person']))[1:floor(random() * 3)::int], '{}'::text[]),
       case when random() < 0.7 then round((case plan when 'Enterprise' then 900 when 'Pro' then 220 else 40 end) * (0.6 + random()))::text end,
       case when sat >= 8 then pg_temp.pick(array['Definitely','Definitely','Probably','Probably','Probably'])
            when sat >= 6 then pg_temp.pick(array['Probably','Probably','Probably','Not sure','Not sure','Not sure','Not sure'])
            else pg_temp.pick(array['Not sure','Not sure','Unlikely','Unlikely','Unlikely']) end,
       case when random() < 0.3 then pg_temp.pick(array['Love the new dashboard.','Pricing tiers are confusing.','Support was quick and helpful.','Please add more integrations.','The mobile app needs work.']) end
from b;

-- ── Onboarding feedback (ANONYMOUS_TRACKED): 15 invited, 12 respond ─────
create temp table _onb_invited on commit drop as
  select e.id, e.department, e.location, e.designation, row_number() over (order by random()) as rn
  from public.employees e where e.employee_code in (select 'NW-' || lpad(i::text, 3, '0') from generate_series(1, 15) i);

with b as (
  select t.*, pg_temp.g(4.1, 0.8) as w from _onb_invited t where rn <= 12
)
insert into public.survey_test_onboarding_feedback
  (submitted_at, definition_version, welcome_rating, has_buddy, days_to_productive, first_week,
   clarity_01, clarity_02, clarity_03, clarity_04, suggestions, resp_department, resp_location, resp_designation)
select date_trunc('hour', now() - random() * interval '25 days'), 1,
       pg_temp.ci(w, 1, 5)::text, case when random() < 0.7 then 'Yes' else 'No' end, pg_temp.ci(pg_temp.g(21, 9), 3, 90)::text,
       (pg_temp.shuf(array['Laptop ready on day one','Met my manager','Met my team','Clear 30-day plan','Completed compliance training']))[1:1 + floor(random() * 4)::int],
       (array['Very dissatisfied','Dissatisfied','Neutral','Satisfied','Very satisfied'])[1 + pg_temp.ci(pg_temp.g(w - 0.6, 0.8), 0, 4)],
       (array['Very dissatisfied','Dissatisfied','Neutral','Satisfied','Very satisfied'])[1 + pg_temp.ci(pg_temp.g(w - 0.6, 0.8), 0, 4)],
       (array['Very dissatisfied','Dissatisfied','Neutral','Satisfied','Very satisfied'])[1 + pg_temp.ci(pg_temp.g(w - 0.6, 0.8), 0, 4)],
       (array['Very dissatisfied','Dissatisfied','Neutral','Satisfied','Very satisfied'])[1 + pg_temp.ci(pg_temp.g(w - 0.6, 0.8), 0, 4)],
       case when random() < 0.5 then pg_temp.pick(array['A clearer 30-day plan would help.','Get laptops ready before day one.','More time with the team early on.']) end,
       department, location, designation
from b;

insert into public.survey_invitations (survey_id, survey_version, employee_id, token_hash, status, sent_at, opened_at, started_at, completed_at, expires_at)
select s.id, 1, t.id, encode(extensions.digest(gen_random_uuid()::text, 'sha256'), 'hex'),
       case when t.rn <= 12 then 'COMPLETED' else 'SENT' end::invitation_status,
       now() - interval '20 days',
       case when t.rn <= 12 then now() - interval '19 days' end,
       case when t.rn <= 12 then date_trunc('hour', now() - interval '18 days') end,
       case when t.rn <= 12 then date_trunc('hour', now() - interval '12 days') end,
       now() + interval '30 days'
from _onb_invited t cross join public.surveys s where s.slug = 'test-onboarding-feedback';

-- Record the seed, then drop the temporary actor.
insert into public.audit_logs (organization_id, user_email, action_type, details)
values (null, 'seed-bot@example.test', 'TEST_DATA_SEEDED',
  jsonb_build_object('customers', 2, 'employees', 50, 'surveys', 4, 'responses', 100,
                     'note', 'Fictional sample data; see ops/seed_test_data.sql'));
delete from public.survey_members where lower(email) = 'seed-bot@example.test';

commit;
